.darma-loader-tw-form-skeleton { display: flex; flex-direction: column; gap: calc(var(--loader-size, 200px) * .035); width: var(--loader-size, 200px); animation: darma-loader-tw-form-skeleton-twPulse calc(var(--loader-speed, 1s) * 1.8) cubic-bezier(.4, 0, .6, 1) infinite; }
.darma-loader-tw-form-skeleton .darma-loader-tw-form-skeleton__label { width: 34%; height: calc(var(--loader-size, 200px) * .04); border-radius: 9999px; background: color-mix(in srgb, var(--loader-color, #64748b) 32%, transparent); }
.darma-loader-tw-form-skeleton .darma-loader-tw-form-skeleton__label.darma-loader-tw-form-skeleton__wide { width: 48%; }
.darma-loader-tw-form-skeleton .darma-loader-tw-form-skeleton__field { height: calc(var(--loader-size, 200px) * .11); margin-bottom: calc(var(--loader-size, 200px) * .025); border-radius: calc(var(--loader-size, 200px) * .025); background: color-mix(in srgb, var(--loader-color, #64748b) 14%, transparent); border: calc(var(--loader-size, 200px) * .008) solid color-mix(in srgb, var(--loader-color, #64748b) 26%, transparent); box-sizing: border-box; }
.darma-loader-tw-form-skeleton .darma-loader-tw-form-skeleton__btn { width: 40%; height: calc(var(--loader-size, 200px) * .095); margin-top: calc(var(--loader-size, 200px) * .02); border-radius: 9999px; background: var(--loader-color, #64748b); }
@keyframes darma-loader-tw-form-skeleton-twPulse { 50% { opacity: .5; } }

